const organizationSettingFields = {
  defaultIssueStatus: z.enum([
    "backlog",
    "todo",
    "in_progress",
    "in_review",
    "done",
    "canceled",
  ]),
  allowPublicProjects: z.boolean(),
  requireTwoFactor: z.boolean(),
  digestHourUtc: z.number().int().min(0).max(23),
  enabledFlagOverrides: z.array(z.string()),
};

/** A complete settings block: missing keys are filled with defaults (seed, new orgs). */
export const organizationSettingsSchema = z.object({
  defaultIssueStatus: organizationSettingFields.defaultIssueStatus.default("backlog"),
  allowPublicProjects: organizationSettingFields.allowPublicProjects.default(false),
  requireTwoFactor: organizationSettingFields.requireTwoFactor.default(false),
  digestHourUtc: organizationSettingFields.digestHourUtc.default(7),
  enabledFlagOverrides: organizationSettingFields.enabledFlagOverrides.default([]),
});

/**
 * A partial settings patch. Deliberately carries no defaults: a key that is
 * absent from the submission must stay absent, so the stored value survives.
 * Explicit `0`, `false` and `[]` are real values and pass through unchanged.
 */
export const organizationSettingsPatchSchema = z
  .object(organizationSettingFields)
  .partial();

